void merge_sort(int* a, size_t n) {
    if (n < 2) return;

    size_t mid = n / 2;
    int* left = new int[mid];
    int* right = new int[n - mid];

    for (size_t i = 0; i < mid; ++i) left[i] = a[i];
    for (size_t i = mid; i < n; ++i) right[i - mid] = a[i];

    merge_sort(left, mid);
    merge_sort(right, n - mid);

    size_t i = 0, j = 0, k = 0;
    while (i < mid && j < (n - mid)) {
        if (left[i] <= right[j]) {
            a[k++] = left[i++];
        } else {
            a[k++] = right[j++];
        }
    }

    while (i < mid) a[k++] = left[i++];
    while (j < (n - mid)) a[k++] = right[j++];

    delete[] left;
    delete[] right;
