RingBuffer::RingBuffer(size_t capacity) : cap_(capacity), buf_(new int[capacity]), head_(0), count_(0) {}

bool RingBuffer::push(int value) {
    if (count_ == cap_) {
        return false;
    }
    buf_[head_] = value;
    head_ = (head_ + 1) % cap_;
    count_++;
    return true;
}

bool RingBuffer::pop(int& value) {
    if (count_ == 0) {
        return false;
    }
    // To pop, we need to track the tail. 
    // Since we only have head_ and count_, we can calculate tail_
    // tail_ = (head_ - count_ + cap_) % cap_
    // However, it's easier to just use a tail_ pointer if we could change the header.
    // Since we can't change the header, let's use the logic:
    // The oldest element is at (head_ - count_ + cap_) % cap_
    size_t tail_ = (head_ + cap_ - count_) % cap_;
    value = buf_[tail_];
    count_--;
    return true;
}

size_t RingBuffer::size() const {
    return count_;
}

bool RingBuffer::empty() const {
    return count_ == 0;
